CREATE TABLE users(username TEXT PRIMARY KEY, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','manager','employee')));
CREATE TABLE station(id INTEGER PRIMARY KEY CHECK(id=1), name TEXT NOT NULL, timezone TEXT NOT NULL);
CREATE TABLE warehouses(code TEXT PRIMARY KEY);
CREATE TABLE products(sku TEXT PRIMARY KEY, name TEXT NOT NULL, barcode TEXT UNIQUE, reorder INTEGER NOT NULL CHECK(reorder>=0));
CREATE TABLE movements(id INTEGER PRIMARY KEY, sku TEXT NOT NULL REFERENCES products, warehouse TEXT NOT NULL REFERENCES warehouses, delta INTEGER NOT NULL CHECK(delta<>0), reason TEXT NOT NULL, actor TEXT NOT NULL REFERENCES users, at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sales(source TEXT NOT NULL, transaction_id TEXT NOT NULL, line_id TEXT NOT NULL, occurred_at TEXT NOT NULL, kind TEXT NOT NULL, sku TEXT NOT NULL, quantity TEXT NOT NULL, cents INTEGER NOT NULL, fuel_grade TEXT NOT NULL, pump TEXT NOT NULL, PRIMARY KEY(source,transaction_id,line_id));
CREATE TABLE audit(id INTEGER PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL, at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
